from datetime import datetime, timedelta

# Mapping from rule_id to fact_name -> (document, field)
RULE_MAP = {
    "lca.wage_105": {
        "offered wage": ("lca_disclosure", "WAGE_RATE_OF_PAY_FROM"),
        "prevailing wage": ("lca_disclosure", "PREVAILING_WAGE"),
    },
    "lca.three_years": {
        "begin date": ("lca_disclosure", "BEGIN_DATE"),
        "end date": ("lca_disclosure", "END_DATE"),
    },
}

def convert_date(value):
    """Convert a value to YYYY-MM-DD. Handles Excel serial dates and common date strings."""
    value = value.strip()
    if not value:
        return None
    # Try to interpret as a number (Excel serial date)
    try:
        serial = float(value)
        # Excel serial date: days since 1899-12-30
        base = datetime(1899, 12, 30)
        dt = base + timedelta(days=serial)
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        pass
    # Try common date string formats
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d-%b-%Y", "%b %d, %Y", "%B %d, %Y"):
        try:
            dt = datetime.strptime(value, fmt)
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            continue
    # If all else fails, return the original string (should not happen)
    return value

def convert_amount(value):
    """Return the amount as a decimal string. Strips whitespace."""
    return value.strip()

def get_values_for_entity(packet_dir, document, field, entity):
    """Return a list of non-empty raw string values for the given entity and field from the CSV file."""
    filename = os.path.join(packet_dir, document + ".csv")
    if not os.path.isfile(filename):
        return []
    values = []
    with open(filename, newline='', encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row.get("CASE_NUMBER", "").strip() == entity.strip():
                val = row.get(field, "")
                if val is not None:
                    val = val.strip()
                if val:
                    values.append(val)
    return values

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]
    with open(manifest_path) as f:
        manifest = json.load(f)
    pairs = manifest["pairs"]
    facts = manifest["facts"]
    output = {}
    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts.get(rule_id, [])
        result = {}
        for fact_name in fact_names:
            if rule_id in RULE_MAP and fact_name in RULE_MAP[rule_id]:
                document, field = RULE_MAP[rule_id][fact_name]
                raw_values = get_values_for_entity(packet_dir, document, field, entity)
                if not raw_values:
                    result[fact_name] = "ABSENT"
                else:
                    # Convert values based on rule type
                    if rule_id == "lca.three_years":
                        converted = [convert_date(v) for v in raw_values]
                    else:
                        converted = [convert_amount(v) for v in raw_values]
                    # Filter out any None from conversion (e.g., empty after strip)
                    converted = [v for v in converted if v is not None]
                    if not converted:
                        result[fact_name] = "ABSENT"
                    else:
                        unique = set(converted)
